// GET /api/dev/app-map — serve the generated .app-map.json (dev aid).
// The JSON is committed + regenerated by `npm run app-map`; this route just
// serves it so the /sysadmin/app-map page can render it without bundling a
// large static file into the client. Read-only; no mutation.
//
// NOTE: this lives under (sysadmin)/api/... so it inherits the sysadmin
// AuthGuard from the (sysadmin) group layout — only sysadmin can read it.
import { NextResponse } from "next/server";
import { readFileSync, existsSync } from "fs";
import path from "path";

export const dynamic = "force-static";
export const revalidate = 3600; // refresh hourly; a fresh `npm run app-map` wins on next build

export async function GET() {
  const candidates = [
    path.resolve(process.cwd(), ".app-map.json"),
    path.resolve(process.cwd(), "..", ".app-map.json"),
    // Docker build context: the repo root carries the generated file.
    path.resolve(process.cwd(), "app", "..", ".app-map.json"),
  ];
  for (const p of candidates) {
    try {
      if (existsSync(p)) {
        const raw = readFileSync(p, "utf8");
        const json = JSON.parse(raw);
        return NextResponse.json(json);
      }
    } catch {
      /* try next candidate */
    }
  }
  return NextResponse.json(
    { error: ".app-map.json not found — run `npm run app-map` first" },
    { status: 404 },
  );
}
